%[text] # Lab 11
% Es 1
f = @(t, y) t.*(2 + t) - y;
real_f = @(t) t.^2 + exp(-t);

a = 0;
b = 2;
h = 0.5;

[T0, Y0] = eulero(f, a:h:b, 1) %[output:811bd6df] %[output:51f474b1]
[T1, Y1] = eulero(f, a:0.25:b, 1) %[output:98fbb2b0] %[output:6a2b4d72]
[T2, Y2] = eulero(f, a:0.125:b, 1) %[output:157e29f1] %[output:56fb38a1]

px = linspace(a, b, 1000);
plot(px, real_f(px), T0, Y0, "--", T1, Y1, "--", T2, Y2, "--"); %[output:14aed5c7]

err = @(T, Y, real_f) max(abs(real_f(T)-Y));

errors = [0.5, err(T0, Y0, real_f); %[output:group:5b1a0c91] %[output:6bccd177]
          0.25, err(T1, Y1, real_f); %[output:6bccd177]
          0.125, err(T2, Y2, real_f);] %[output:group:5b1a0c91] %[output:6bccd177]

%%
%[text] ## Es 3
%%
%[text] ## C1

h = [0.1, 0.01, 0.001, 0.0001];
a = 0;
b = 2;

y0 = 1;
f_1 = @(t, y) -2.*t.*y.^2;
real_f = @(t) 1./(1 + t.^2);

%derivative
syms t y
%f1 = -2*t*y^2;
df1_dy = diff(f_1(t, y), y);
f1_dy_num = matlabFunction(df1_dy, 'Vars', [t, y]);
%f1_dy_num = matlabFunction(df1_dy);


px = linspace(a, b, 1000);
plot(px, real_f(px)); %[output:276622e6]
hold on; %[output:276622e6]

toll = 0.001;
nitmax = 100;

err_func = @(T, vals, f) max(abs(vals - f(T)));
errors_table = [];

for h_v=h
    [T,Y] = eulimp(f_1,a:h_v:b,y0,f1_dy_num,toll,nitmax);
    errors_table = [errors_table; h_v, err_func(T, Y, real_f)];
    plot(T, Y, "--"); %[output:276622e6]
end
hold off; %[output:276622e6]

format short e
errors_table %[output:1f57b5d9]

%%
%[text] ## C2
h = [0.1, 0.01, 0.001, 0.0001];
a = 0;
b = 2;

y0 = 1;
f_1 = @(t, y) -25.*y;
real_f = @(t) exp(-25.*t);

%derivative
syms t y
df1_dy = diff(f_1(t, y), y);
f1_dy_num = matlabFunction(df1_dy, 'Vars', [t, y]);
%f1_dy_num = matlabFunction(df1_dy);
%f1_dy_num = @(t, y) -25;

px = linspace(a, b, 1000);
plot(px, real_f(px)); %[output:3a9743e9]
hold on; %[output:3a9743e9]

toll = 1e-6;
nitmax = 100;

err_func = @(T, vals, f) max(abs(vals - f(T)));
errors_table = [];

for h_v=h
    [T,Y] = eulimp(f_1,a:h_v:b,y0,f1_dy_num,toll,nitmax);
    errors_table = [errors_table; h_v, err_func(T, Y, real_f)];
    plot(T, Y, "--"); %[output:3a9743e9]
end
hold off; %[output:3a9743e9]

format short e
errors_table %[output:2f206407]

%%
%[text] ## Es di riepilogo
f = @(t, y) t.^2.*(1 - 3.*y);
f_real = @(t) (1/3).*(1+5.*exp(-t.^3));
a = 0;
b = 3;
y0 = 2;
h = [0.1, 0.01, 0.001];

err = @(T, Y, target_f) max(abs(target_f(T) - Y));
results_table = [];

syms t y;
dfy = diff(f(t, y), y);
dfy = matlabFunction(dfy, "Vars", [t y]);

hold on; %[output:3e4f7173]
px = linspace(a, b, 1000);
plot(px, f_real(px)); %[output:3e4f7173]
for h_v=h
    t_range = a:h_v:b;
    [T, Y] = heun(f, t_range, y0);
    plot(T, Y, "--"); %[output:3e4f7173]
    T_heun = T;
    Y_heun = Y;

    [T, Y] = cranknic(f,T,y0,dfy,0.0001,100);
    plot(T, Y, "--");

    results_table = [results_table;
        h_v, err(T_heun, Y_heun, f_real), err(T, Y, f_real);];
end
hold off; %[output:3e4f7173]
format short e;
results_table %[output:1a4907a6]

